import json
R=Path(__file__).resolve().parent / "Buyer"
FILES={'06_codex-practice/11_csv-margin-lab/orders.csv': 'order_id,revenue,cost\nA,120,72\nB,80,60\nC,0,0\n', '06_codex-practice/11_csv-margin-lab/margin_report.py': '"""Offline educational CSV report. Monetary units must be consistent; no accounting advice."""\nimport csv,json,sys\nfrom decimal import Decimal,InvalidOperation\n\ndef number(value):\n    try:\n        n=Decimal(str(value).strip())\n    except (InvalidOperation,ValueError):\n        raise ValueError(\'Use a finite non-negative decimal with a dot separator\')\n    if not n.is_finite() or n<0:\n        raise ValueError(\'Use a finite non-negative decimal\')\n    return n\n\ndef build_report(rows):\n    items=[];seen=set();revenue=Decimal(0);cost=Decimal(0)\n    for row in rows:\n        key=str(row.get(\'order_id\',\'\')).strip()\n        if not key or key in seen:raise ValueError(\'Missing or duplicate order_id\')\n        seen.add(key);r=number(row.get(\'revenue\',\'\'));c=number(row.get(\'cost\',\'\'))\n        items.append({\'order_id\':key,\'revenue\':str(r),\'cost\':str(c),\'gross_profit\':str(r-c),\n                      \'gross_margin_percent\':None if r==0 else str(((r-c)/r*100).quantize(Decimal(\'0.01\')))})\n        revenue+=r;cost+=c\n    return {\'orders\':items,\'totals\':{\'revenue\':str(revenue),\'cost\':str(cost),\'gross_profit\':str(revenue-cost),\n             \'gross_margin_percent\':None if revenue==0 else str(((revenue-cost)/revenue*100).quantize(Decimal(\'0.01\')))},\n             \'scope\':\'Gross margin from supplied revenue and cost only. Fees, tax, shipping and refunds are not modelled.\'}\n\ndef main(path):\n    with open(path,newline=\'\',encoding=\'utf-8-sig\') as f:\n        reader=csv.DictReader(f)\n        if not {\'order_id\',\'revenue\',\'cost\'}<=set(reader.fieldnames or []):raise ValueError(\'Required headers: order_id,revenue,cost\')\n        return build_report(reader)\n\nif __name__==\'__main__\':\n    try:\n        if len(sys.argv)!=2:raise ValueError(\'Usage: python margin_report.py orders.csv\')\n        print(json.dumps(main(sys.argv[1]),indent=2))\n    except (ValueError,OSError) as error:\n        print(json.dumps({\'error\':str(error)}),file=sys.stderr);sys.exit(1)\n', '06_codex-practice/11_csv-margin-lab/AGENTS.md': '# Local practice instructions\n\nRead README.md before editing. Use the sample CSV to reproduce current behaviour.\nUse only the Python standard library. Do not add network access, sending, scheduling or live account connections.\nKeep the original sample intact; use a copy for experiments.\nRun the supplied unittest file and the sample CLI command after relevant changes.\nExplain the original failure, focused correction, actual checks and remaining limits.\nNever store credentials or claim that local tests prove a production integration works.\n', '06_codex-practice/11_csv-margin-lab/test_margin.py': "import unittest\nfrom margin_report import build_report,number\n\nclass MarginTests(unittest.TestCase):\n    def test_sample_aggregate(self):\n        r=build_report([{'order_id':'A','revenue':'120','cost':'72'},{'order_id':'B','revenue':'80','cost':'60'},{'order_id':'C','revenue':'0','cost':'0'}])\n        self.assertEqual(r['totals']['gross_margin_percent'],'34.00')\n        self.assertEqual(r['totals']['gross_profit'],'68')\n        self.assertIsNone(r['orders'][2]['gross_margin_percent'])\n    def test_empty(self):self.assertIsNone(build_report([])['totals']['gross_margin_percent'])\n    def test_duplicate(self):\n        with self.assertRaises(ValueError):build_report([{'order_id':'A','revenue':1,'cost':0}]*2)\n    def test_missing_id(self):\n        with self.assertRaises(ValueError):build_report([{'revenue':1,'cost':0}])\n    def test_invalid_numbers(self):\n        for n in ['NaN','Infinity','-1','','one','1,2']:\n            with self.subTest(n=n),self.assertRaises(ValueError):number(n)\n    def test_cost_exceeds_revenue(self):self.assertEqual(build_report([{'order_id':'X','revenue':10,'cost':20}])['orders'][0]['gross_margin_percent'],'-100.00')\n\nif __name__=='__main__':unittest.main()\n", '06_codex-practice/11_csv-margin-lab/README.md': "# CSV margin lab\n\nRun from this folder with Python 3.10 or later:\n\n```text\npython margin_report.py orders.csv\npython -m unittest test_margin.py\n```\n\nThe script reads the supplied CSV and prints JSON. It makes no network calls and does not modify input files. Use one consistent currency and dot decimal separators. Required headers are order_id,revenue,cost. Empty data with valid headers returns zero totals and an undefined margin. Missing IDs, duplicate IDs, non-finite numbers and negative values are rejected. Refunds, fees, taxes and currency conversion are outside this lab's scope.\n\nExpected sample totals: revenue 200, cost 132, gross profit 68, gross margin 34.00 percent. Order C has an undefined margin, represented by null, because its revenue is zero. Aggregate margin is calculated from aggregate revenue and cost, not an average of row percentages.\n\nPractice: change B's cost to 50 in a copy of the CSV. Re-run the report and independently calculate the new total. Then try a missing ID and confirm the script exits with an error. Keep the original sample as a known-good input. Ask a coding agent for a narrow change only after describing the current reproduction and expected behaviour.\n\nThis is a local educational starter, not production accounting software. Passing these tests does not verify every possible CSV or business rule.\n", '06_codex-practice/12_action-register-lab/AGENTS.md': '# Local practice instructions\n\nRead README.md before editing. Use the sample CSV to reproduce current behaviour.\nUse only the Python standard library. Do not add network access, sending, scheduling or live account connections.\nKeep the original sample intact; use a copy for experiments.\nRun the supplied unittest file and the sample CLI command after relevant changes.\nExplain the original failure, focused correction, actual checks and remaining limits.\nNever store credentials or claim that local tests prove a production integration works.\n', '06_codex-practice/12_action-register-lab/action_report.py': '"""Validate and summarize a local action register; never sends or schedules anything."""\nimport csv,json,sys\nfrom datetime import date\n\ndef build_report(rows):\n    seen=set();counts={\'open\':0,\'done\':0,\'blocked\':0};actions=[]\n    for row in rows:\n        item={key:str(row.get(key,\'\')).strip() for key in (\'id\',\'title\',\'owner\',\'due\',\'status\')}\n        if not item[\'id\'] or item[\'id\'] in seen:raise ValueError(\'Missing or duplicate id\')\n        if not item[\'title\']:raise ValueError(\'Missing title\')\n        if not item[\'owner\']:raise ValueError(\'Missing owner: record unconfirmed explicitly if not assigned\')\n        if item[\'status\'] not in counts:raise ValueError(\'Status must be open, done or blocked\')\n        if item[\'due\']:\n            try:parsed=date.fromisoformat(item[\'due\'])\n            except ValueError:raise ValueError(\'Due date must use YYYY-MM-DD or be blank\')\n            if parsed.isoformat()!=item[\'due\']:raise ValueError(\'Due date must use YYYY-MM-DD\')\n        seen.add(item[\'id\']);counts[item[\'status\']]+=1;actions.append(item)\n    return {\'total\':len(actions),\'counts\':counts,\'actions\':actions,\n            \'unconfirmed_owners\':[x[\'id\'] for x in actions if x[\'owner\'].lower()==\'unconfirmed\'],\n            \'scope\':\'Local validation only; no task creation, messaging or scheduling.\'}\n\ndef main(path):\n    with open(path,newline=\'\',encoding=\'utf-8-sig\') as f:\n        reader=csv.DictReader(f)\n        if not {\'id\',\'title\',\'owner\',\'due\',\'status\'}<=set(reader.fieldnames or []):raise ValueError(\'Required headers: id,title,owner,due,status\')\n        return build_report(reader)\n\nif __name__==\'__main__\':\n    try:\n        if len(sys.argv)!=2:raise ValueError(\'Usage: python action_report.py actions.csv\')\n        print(json.dumps(main(sys.argv[1]),indent=2))\n    except (ValueError,OSError) as error:\n        print(json.dumps({\'error\':str(error)}),file=sys.stderr);sys.exit(1)\n', '06_codex-practice/12_action-register-lab/actions.csv': 'id,title,owner,due,status\nA01,Send revised file,Sam,2026-11-06,open\nA02,Confirm print proof,Alex,2026-11-05,done\nA03,Test delivery link,unconfirmed,,blocked\n', '06_codex-practice/12_action-register-lab/README.md': '# Action register lab\n\nRun from this folder with Python 3.10 or later:\n\n```text\npython action_report.py actions.csv\npython -m unittest test_actions.py\n```\n\nThe script reads a CSV, validates required fields and prints a JSON summary. It does not create tasks in any app, send reminders or access a calendar. Required headers: id,title,owner,due,status. Supported statuses are open, done and blocked, in lowercase. Dates use YYYY-MM-DD or may be blank when not agreed. Use the literal owner unconfirmed when no owner has been assigned; the report flags these records.\n\nExpected sample: three actions; one open, one done and one blocked. A03 appears in unconfirmed_owners. This explicitly preserves uncertainty instead of guessing who should do the work.\n\nPractice: duplicate A01 and confirm validation fails. Enter 2026-02-30 and check that the invalid date is rejected. Remove the duplicate and invalid date, then re-run. Keep your test output with a short handoff explaining what was and was not checked.\n\nRepeated runs print the same report for the same input and make no external changes. A future connected workflow would need its own duplicate handling, authorization and account-specific tests. Those live integrations are not part of this starter.\n', '06_codex-practice/12_action-register-lab/test_actions.py': "import unittest\nfrom action_report import build_report\n\nclass ActionTests(unittest.TestCase):\n    def row(self,**kwargs):\n        r=dict(id='A01',title='Review',owner='Sam',due='2026-11-06',status='open');r.update(kwargs);return r\n    def test_valid(self):self.assertEqual(build_report([self.row()])['counts']['open'],1)\n    def test_unconfirmed(self):self.assertEqual(build_report([self.row(owner='unconfirmed',due='')])['unconfirmed_owners'],['A01'])\n    def test_duplicate(self):\n        with self.assertRaises(ValueError):build_report([self.row(),self.row()])\n    def test_invalid_date(self):\n        with self.assertRaises(ValueError):build_report([self.row(due='2026-02-30')])\n    def test_non_iso_date(self):\n        with self.assertRaises(ValueError):build_report([self.row(due='06/11/2026')])\n    def test_missing_owner(self):\n        with self.assertRaises(ValueError):build_report([self.row(owner='')])\n    def test_unknown_status(self):\n        with self.assertRaises(ValueError):build_report([self.row(status='probably')])\n    def test_empty(self):self.assertEqual(build_report([])['total'],0)\n\nif __name__=='__main__':unittest.main()\n"}
for name,content in FILES.items():
 p=R/name
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(content,encoding="utf-8")
